TLM.f("Sancti/02-22",{"officium":"In Cathedra S. Petri Apostoli","rule":["ex C4;","Gloria","Credo","Prefatio=Apostolis","Sub unica conclusione"],"fallback":"Commune/C4","sections":{"Introitus":[{"k":"ref","la":"Eccli 45:30"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui beáto Petro Apóstolo tuo, collátis clávibus regni cœléstis, ligándi atque solvéndi pontifícium tradidísti: concéde; ut, intercessiónis ejus auxílio, a peccatórum nostrórum néxibus liberémur:"},{"k":"macro","name":"Qui vivis"},{"k":"sep"},{"k":"rubric","la":"Commemoratio S. Pauli"},{"k":"text","la":"Deus, qui multitúdinem géntium beáti Pauli Apóstoli prædicatióne docuísti: da nobis, quǽsumus; ut, cujus commemoratiónem cólimus, ejus apud te patrocínia sentiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet 1:1-7"},{"k":"text","la":"Petrus, Apóstolus Jesu Christi, eléctis ádvenis dispersiónis Ponti, Galátiæ, Cappadóciæ, Asiæ et Bithýniæ secúndum præsciéntiam Dei Patris, in sanctificatiónem Spíritus, in obœdiéntiam, et aspersiónem sánguinis Jesu Christi: grátia vobis et pax multiplicétur. Benedíctus Deus et Pater Dómini nostri Jesu Christi, qui secúndum misericórdiam suam magnam regenerávit nos in spem vivam, per resurrectiónem Jesu Christi ex mórtuis, in hereditátem incorruptíbilem et incontaminátam et immarcescíbilem, conservátam in cœlis in vobis, qui in virtúte Dei custodímini per fidem in salútem, parátam revelári in témpore novíssimo. In quo exsultábitis, módicum nunc si opórtet contristári in váriis tentatiónibus: ut probátio vestræ fídei multo pretiósior auro [quod per ignem probatur] inveniátur in laudem et glóriam et honórem, in revelatióne Jesu Christi, Dómini nostri."}],"Graduale":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 106:8"},{"k":"text","la":"Confitéantur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum"},{"k":"ref","la":"Matt 6:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in Ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus; et mirabília ejus fíliis hóminum.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Matt 16:18-19"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam."},{"k":"text","la":"Et portæ ínferi non prævalébunt advérsus eam: et tibi dabo claves regni cœlórum.","mark":"V"},{"k":"text","la":"Quodcúmque ligáveris super terram, erit ligátum et in cœlis.","mark":"V"},{"k":"text","la":"Et quodcúmque sólveris super terram, erit solútum et in cœlis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:13-19"},{"k":"text","la":"In illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis."}],"Offertorium":[{"k":"ref","la":"Matt 16:18-19"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam: et portæ ínferi non prævalébunt advérsus eam: et tibi dabo claves regni cœlórum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, preces et hóstias beáti Petri Apóstoli comméndet orátio: ut, quod pro illíus glória celebrámus, nobis prosit ad véniam."},{"k":"macro","name":"Per Dominum"},{"k":"sep"},{"k":"rubric","la":"Pro S. Paulo"},{"k":"text","la":"Apóstoli tui Pauli précibus, Dómine, plebis tuæ dona sanctífica: ut, quæ tibi tuo grata sunt institúto, gratióra fiant patrocínio supplicántis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Lætíficet nos, Dómine, munus oblátum: ut, sicut in Apóstolo tuo Petro te mirábilem prædicámus; sic per illum tuæ sumámus indulgéntiæ largitátem."},{"k":"macro","name":"Per Dominum"},{"k":"sep"},{"k":"rubric","la":"Pro S. Paulo"},{"k":"text","la":"Sanctificáti, Dómine, salutári mystério: quǽsumus; ut nobis ejus non desit orátio, cujus nos donásti patrocínio gubernari."},{"k":"macro","name":"Per Dominum"}]},"hr":{"c02c414c737dacfd":{"t":"Sir 45, 30, Ps 131, 1\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu. (Ps 131, 1) Spomeni se, Gospodine, Davida i sve njegove krotkosti.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu.","kn":"(Grkv. 45, 30). Gospodin je sklopio s njime savez mira i učinio ga knezom, da zauvijek bude u svećeničkom dostojanstvu. (Ps. 131, 1). Sjeti se, Gospodine, Davida i sve njegove pobožnosti. Slava Ocu. Gospodin ...","knRef":"Kniewald 1942, str. 478–479 (snimka 240) (OCR)"},"12b566b864ba22e4":{"t":"Bože, koji si blaženom Petru apostolu predao ključeve kraljevstva nebeskoga i time velikosvećeničku vlast vezanja i odrješivanja, daj da se po njegovu zagovoru izbavimo od veza naših grijeha.\n<i>Koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si blaženomu Petru, apostolu svome, dao ključeve kraljevstva nebeskoga i vrhovnu vlast vezati i razriješiti, podaj, da se po njegovu zagovoru izbavimo od naših grijeha.","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"e062fb76a2ea52a3":{"t":"Bože, koji si mnoštvo naroda poučio propovijedanjem blaženoga Pavla apostola, daj nam. molimo, da mi koji danas slavimo njegov spomen osjetimo njegovu zaštitu kod tebe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si mnoge narode poučio propovijedanjem blaženoga Pavla apostola, molimo Te, da nas kod Tebe zagovara onaj, kojega spomen slavimo.","knRef":"Kniewald 1942, str. 478–479 (snimka 240) (OCR)"},"90acaadd25cbee4c":{"t":"1 Pt 1, 1-7\nČitanje Poslanice bl. Petra apostola. Petar, apostol Isusa Krista, raspršenim pridošlicama po Pontu, Galaciji, Kapadociji, Aziji i Bitiniji, izabranim po predznanju Boga Oca na posvetu Duha, da slušaju i budu poškropljeni krvlju Isusa Krista. Umnožila vam se milost i mir! Blagoslovljen Bog i Otac našega Gospodina Isusa Krista koji nas je po svome velikom milosrđu preporodio uskrsnućem Isusa Krista od mrtvih, da bismo se željno nadali neraspadljivoj, neokaljanoj, neuveloj baštini, sačuvanoj na nebu za one, koje po Božjoj moći čuva vjera, da postignete spas koji je pripravljen da se objavi na sudnji dan. Tada ćete se veseliti što se sada malo žalostite zbog raznih kušnja da vaša prokušana vjera dragocjenija od zlata iskušana u vatri bude dostojna hvale, slave, časti, kada se pojavi naš Gospodin Isus Krist.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.98)"},"af0a8c5b55f66b4e":{"t":"Ps 106, 32 i 31\nNeka ga uzvisuju u narodnom zboru, neka ga hvale u vijeću staraca. Neka hvale Gospodina za dobrotu njegovu, za čudesa njegova sinovima ljudskim.\n\nMt 16, 18-19\nTi si Petar-Stijena, i na toj stijeni sazidat ću Crkvu svoju. I vrata paklena neće je nadvladati. A tebi ću dati ključeve kraljevstva nebeskoga. Što god svežeš na zemlji bit će svezano i na nebu. A što god razriješiš na zemlji bit će razriješeno i na nebu.","kn":"(Ps. 106, 32, 31). Slavite ga u crkvi i hvalite ga u skupštini starješina. Neka uzdižu milosrđe Gospodinovo i divna djela njegova na sinovima ljudskim.\n\nTi si Petar i na toj ču stijeni sazidati crkvu svoju i vrata je paklena ne će nadvladati. I tebi ću dati ključeve kraljevstva nebeskoga: štogod svežeš na zemlju, bit će svezano i na nebesima; i štogod razriješiš na zemlji, bit će razriješeno i na nebesima.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"2eaad8272860ffbe":{"t":"Mt 16, 13-19\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Kad Isus dođe u krajeve Cezareje Filipove, upita učenike: Što govore ljudi, tko je Sin Čovječji? Oni rekoše: Jedni da je Ivan Krstitelj; drugi da je Ilija; treći opet da je Jeremija ili koji od proroka. Kaže im Isus: A vi, što vi kažete, tko sam ja? Šimun Petar prihvati i reče: Ti si Krist-Pomazanik, Sin Boga živoga. Nato Isus reče njemu: Blago tebi, Šimune, sine Jonin, jer ti to ne objavi tijelo i krv, nego Otac moj, koji je na nebesima. A ja tebi kažem: Ti si Petar-Stijena, i na toj stijeni sazidat ću Crkvu svoju. I vrata paklena neće je nadvladati. A tebi ću dati ključeve kraljevstva nebeskoga. Što god svežeš na zemlji bit će svezano i na nebu. A što god razriješiš na zemlji bit će razriješeno i na nebu.","kn":"t Slijedi sveto evanđelje po Mateju (16, 13-19). U ono vrijeme dođe Isus u krajeve Cezareje Filipove i upita svoje učenike; Sto kažu ljudi; Tko je Sin čovječji? Oni odgovore; Jedni kažu. da je Ivan Krstitelj, drugi Ilija, a drugi da je Jeremija ili kojigod od proroka. Isus ih upita; A vi što kažete; Tko sam ja? Simun Petar odgovori: Ti si Krist, Sin živoga Boga. Isus mu nato reče; Blago tebi, Simune, sine Jonin! Jer ti to nije objavio tijelo i krv, nego moj nebeski Otac. A ja tebi kažem: Ti si Petar, i na toj stijeni sagradit cu svoju Crkvu, i paklena je vrata ne će nadvladati. Tebi ću dati ključeve nebeskoga kraljevstva, 1 štogod svežeš na zemlji, bit će svezano i na ne-’ bu, 1 štogod razriješiš na zemlji, bit će razriješeno i na nebu.","knRef":"Kniewald 1942, str. 616–617 (snimka 309) (OCR)"},"f20c13573ded523b":{"t":"Mt 16, 18-19\nTi si Petar-Stijena, i na toj stijeni sazidat ću Crkvu svoju. I vrata paklena neće je nadvladati. A tebi ću dati ključeve kraljevstva nebeskoga. Što god svežeš na zemlji bit će svezano i na nebu. A što god razriješiš na zemlji bit će razriješeno i na nebu.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.71)"},"0fe93625122c551c":{"t":"Molitva blaženoga Petra apostola neka preporuči, molimo, Gospodine, molitve i darove tvoje Crkve, da nama koristi za oproštenje što njemu na čast svetkujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, neka prošnje i žrtve Tvoje Crkve preporuči molitva blaženoga Petra Apostola, da nam uskoristi za oproštenje, što svetkujemo na njegovu slavu, po G. n.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"f43c659e380d72b6":{"t":"Posveti, Gospodine, po molitvama svoga apostola Pavla darove svoga naroda, koji su ti mili jer si ih ustanovio, pa neka ti budu miliji po zagovoru našega zaštitnika.","kn":"Posveti, Gospodine, molitvama apostola svoga Pavla dare puka svoga, da ono, što Ti je ugodno, jer si to sam ustanovio, bude Tebi još ugodnije poradi njegova zagovora, po G. n. I. K.","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"a937e43128eeb79a":{"t":"Mt 16, 18\nTi si Petar–stijena, i na toj stijeni sazidat ću svoju Crkvu.","kn":"Ti si Petar 1 na toj ću stijeni sazidati crkvu svoju.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"4dbe0d4385fb1374":{"t":"Neka nas, Gospodine, razveseli prikazani dar da po tvome apostolu Petru tako primimo tvoje obilno oproštenje kao što u njemu slavimo tvoja čudesa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka nas obraduje. Gospodine, žrtvovani dar, te kao što veličamo čudesa Tvoja u Tvom apostolu Petru, takonam po njemu udijeli obilje Tvog ciproštenja, -po G. n.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"cd9242e62e1257e1":{"t":"Posvećeni, Gospodine, spasonosnom tajnom molimo, da nam ne bude uskraćena molitva onoga kojega si nam darovao kao zaštitnika i upravitelja."}}});
